mapper.select:
 WHERE t.project_id=#{projectId}
AND t.status=#{status}
AND t.assignee_id=#{assigneeId}
AND t.priority=#{priority}
AND t.title LIKE CONCAT('%',#{query},'%')
AND t.due_date < #{today} AND t.status!='DONE'
ORDER BY CASE t.priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END,t.id DESC

mapper.update:
UPDATE task SET title=#{title},description=#{description},status=#{status},priority=#{priority},
 assignee_id=#{assigneeId},due_date=#{dueDate},version=version+1,updated_at=CURRENT_TIMESTAMP
WHERE id=#{id} AND project_id=#{projectId} AND version=#{version}
